sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) { //MSSTRUSTES-279
   if (isLoading || newValue === '') {
      return;
   }

   var categoryValue = g_form.getValue('category_aml');
   var newEnrolmentCategory = 'new_enrollment'; 
   var closedCompleteState = '3'; 

   if (categoryValue == newEnrolmentCategory && newValue == closedCompleteState) {
	setTimeout(function() {
         g_form.save();
      }, 2000); // 2000 milliseconds = 2 seconds
   }
}
